parameters.jsCode:
// ─────────────────────────────────────────────────────────────────────────────
// Merge Media
// Every media branch ends here, so this is where the turn is described once:
//   • content   — what the merchant should read in the inbox
//   • mediaUrl  — a durable copy of what the customer sent, if one was stored
//   • mediaType — 'image' | 'audio' | 'text'
// ─────────────────────────────────────────────────────────────────────────────

const item = $input.item.json;
const payload = $('When Called by Platform').first().json;

const resolvedMessage = item.resolvedMessage || '';
const originalMessage = String(payload.userMessage || '').trim();
const platformMessageId = String(payload.messageId || '');
const replyToMessageId = String(payload.replyToMessageId || '');

// A card tap arrives as [ORDER_CARD:<productId>]. The marker is for the agent,
// so it is stripped from the copy the merchant sees in the inbox only.
const displayMessage = originalMessage.replace(/\[ORDER_CARD:[^\]]*\]/gi, '').trim();

// A photo or voice note carries no text of its own, so the description or
// transcript is all there is to show until the attachment loads. When the
// customer did type something, those are their own words and win.
const content = displayMessage || (originalMessage ? '🛒 Order' : resolvedMessage);

// Asking a node that did not run is how n8n reports "this branch did not
// execute" — so the failure itself is the answer.
const uploadedUrl = (nodeName) => {
  try {
    const url = $(nodeName).first().json.cloudinaryUrl;
    return typeof url === 'string' && url ? url : '';
  } catch (err) {
    return '';
  }
};

const mediaUrl =
  uploadedUrl('Merge Image Upload') ||
  uploadedUrl('Merge Audio Upload');

// Without a durable URL the inbox must fall back to text, otherwise it would
// try to render an attachment that no longer exists.
const mediaType = mediaUrl ? (payload.mediaType === 'image' ? 'image' : 'audio') : 'text';

// ── Billing ────────────────────────────────────────────────────────────────
// A media credit is only fair when the model actually did the media work: a
// photo whose download failed still gets a reply, but nobody paid Gemini for it.
const geminiAnswered = (nodeName) => {
  try {
    const out = $(nodeName).first().json;
    return !!(out && out.candidates);
  } catch (err) {
    return false;
  }
};

const isImage = geminiAnswered('Gemini Vision');

const audioBytes = (() => {
  try {
    const size = $('Normalize Audio Type').first().json.audioBytes;
    return typeof size === 'number' && size > 0 ? size : 0;
  } catch (err) {
    return 0;
  }
})();

// Voice notes are 16 kHz mono, so size converts to duration at 16,000 bits per
// second. A minute is what the platform's credit rule is priced in.
const audioMinutes = geminiAnswered('Gemini Transcribe') && audioBytes > 0
  ? (audioBytes * 8) / 16000 / 60
  : 0;

// Ready-to-inject SQL literals: the URL comes from Cloudinary, but escaping it
// here keeps the query below free of hand-built quotes.
const sqlLiteral = (value) => "'" + String(value).replace(/'/g, "''") + "'";

return {
  json: {
    content,
    resolvedMessage,
    mediaUrl,
    mediaType,
    mediaUrlSql: mediaUrl ? sqlLiteral(mediaUrl) : 'NULL',
    mediaTypeSql: mediaUrl ? sqlLiteral(mediaType) : 'NULL',
    platformMessageIdSql: platformMessageId ? sqlLiteral(platformMessageId) : 'NULL',
    replyToMessageIdSql: replyToMessageId ? sqlLiteral(replyToMessageId) : 'NULL',
    audioBytes,
    isImage,
    audioMinutes
  }
};

const rows = $input.all().map((row) => row.json);
const knowledgeContext = rows.filter((row) => !row.isQuotedContext).map((row) => row.content).filter(Boolean).join('

---

');
const quotedContext = rows.find((row) => row.isQuotedContext)?.content || '';
return [{ json: { knowledgeContext, quotedContext, resolvedMessage: $('Merge Media').item.json.resolvedMessage } }];

const rawOutput = $('AI Agent').item.json || {};

const raw = String(rawOutput.output || rawOutput.replyText || rawOutput.text || '');

// Unwrap HTTP Request Tool output; n8n may wrap the response in response/body/data.
const parseToolObservation = (observation) => {
  if (observation && typeof observation === 'object') return observation;
  if (typeof observation !== 'string') return null;
  try { return JSON.parse(observation); } catch (err) { return null; }
};
const unwrapToolResult = (value) => {
  if (Array.isArray(value)) {
    for (const entry of value) {
      const unwrapped = unwrapToolResult(entry);
      if (unwrapped && typeof unwrapped.success === 'boolean') return unwrapped;
    }
    return null;
  }
  if (!value || typeof value !== 'object') return null;
  if (typeof value.success === 'boolean') return value;
  for (const key of ['response', 'body', 'data']) {
    const unwrapped = unwrapToolResult(value[key]);
    if (unwrapped) return unwrapped;
  }
  return null;
};
const orderReceipt = (Array.isArray(rawOutput.intermediateSteps) ? rawOutput.intermediateSteps : [])
  .filter((step) => step && step.action && step.action.tool === 'Create Order')
  .map((step) => unwrapToolResult(parseToolObservation(step.observation)))
  .find((result) => result && result.success === true && result.orderReceipt && result.orderReceipt.template_type === 'receipt')
  ?.orderReceipt || null;

// [CARDS] productId1,productId2 is how the agent asks for a product carousel.
// Only ids that survive validation are forwarded to SQL, so a hallucinated line
// can never turn into SQL injection or an unbounded query.
// A bare [CARDS] (no ids) is a browse request: Fetch Product Cards then
// sends the catalogue. This is the safety net for 'what do you sell?' when
// Product Lookup returned nothing the model could name.
const cardMatch = raw.match(/\[CARDS\][\t]*([^\n\r]+)?/i);
const carouselIds =
  cardMatch && cardMatch[1]
    ? [...new Set(cardMatch[1].split(',').map((id) => id.trim()).filter((id) => /^[A-Za-z0-9_-]+$/.test(id)))].slice(0, 10)
    : [];
const imgs = [];
const re = /\[IMG\]\s*(\S+)/g;
let m;
while ((m = re.exec(raw)) !== null) imgs.push(m[1]);
let replyText = raw.replace(/\[CARDS\][\t]*[^\n\r]*/gi, '').replace(/\[IMG\]\s*\S+/g, '').replace(/\n{3,}/g, '\n\n').trim();

const model = $('Fetch Bot Config').item.json.model || 'unknown';

// Only the branch that ran has an item; the failure is the answer.
const merge = (() => {
  try {
    return $('Merge Media').item.json;
  } catch (err) {
    return {};
  }
})();

// Token count is a character-based ESTIMATE — it is only a fallback for the
// billing API. The platform recomputes cost from live OpenRouter prices, and
// Step 7 (exact reconciler) replaces this with n8n's own metadata.tracing
// counts. We do NOT compute cost here anymore: price must have exactly one
// source of truth, and a hardcoded rate is what made the old numbers wrong.
const systemPromptStr = String($('Fetch Bot Config').item.json.systemPrompt || '');
const knowledgeCtxStr = String($('Build Context').item.json.knowledgeContext || '');
const userMsgStr = String($('Merge Media').item.json.resolvedMessage || '');

// Deterministic fallback for 'show me the photos' requests. The agent marker is
// preferred, but a model that ignores it must not leave the customer with a
// promise of images and no image: when the message explicitly asks for photos
// in a text turn, Fetch Product Cards falls back to the catalogue (products
// whose name appears in the message come first).
const mediaTypeForCards = String($('When Called by Platform').item.json.mediaType || 'text');
const asksForImages = /(?:^|[^a-z])(images?|photos?|pictures?|pics?|gallery)(?:[^a-z]|$)|ছবি|ফটো/i.test(userMsgStr);
const bengaliBrowseTerms = [String.fromCharCode(0x0995,0x09C0,0x0020,0x0995,0x09C0,0x0020,0x0986,0x099B,0x09C7), String.fromCharCode(0x0995,0x09BF,0x0020,0x0995,0x09BF,0x0020,0x0986,0x099B,0x09C7), String.fromCharCode(0x0995,0x09C0,0x0020,0x0995,0x09C0,0x0020,0x09AA,0x09CD,0x09B0,0x09CB,0x09A1,0x09BE,0x0995,0x09CD,0x099F), String.fromCharCode(0x0995,0x09C0,0x0020,0x0995,0x09C0,0x0020,0x09AA,0x09A3,0x09CD,0x09AF), String.fromCharCode(0x09B8,0x09AC,0x0020,0x09AA,0x09CD,0x09B0,0x09CB,0x09A1,0x09BE,0x0995,0x09CD,0x099F,0x0020,0x09A6,0x09C7,0x0996,0x09BE,0x0993), String.fromCharCode(0x09AA,0x09CD,0x09B0,0x09CB,0x09A1,0x09BE,0x0995,0x09CD,0x099F,0x0020,0x09A6,0x09C7,0x0996,0x09BE,0x0993)];
const isBroadBrowse = /\b(?:catalog(?:ue)?|what (?:products|items) do you (?:sell|have)|show (?:me )?(?:all )?(?:products|items)|browse products)\b/i.test(userMsgStr) || bengaliBrowseTerms.some((term) => userMsgStr.includes(term));
const wantsCards = cardMatch !== null || isBroadBrowse;
const sq = String.fromCharCode(39);
const userMessageSql = userMsgStr.replace(/\s+/g, ' ').trim().slice(0, 500).replace(/'/g, sq + sq);
const quotedSnippetSql = String($('Build Context').item.json.quotedContext || '').slice(0, 500).replace(/'/g, sq + sq);
const quotedSnippetSqlLiteral = quotedSnippetSql ? sq + quotedSnippetSql + sq : 'NULL';
const fullInputStr = systemPromptStr + '\n' + knowledgeCtxStr + '\n' + userMsgStr;

// Bengali tokenises far worse than Latin script — roughly one token per 1.7
// characters against one per 3.8 — so a single divisor systematically
// under-counts exactly the conversations this product exists for. The estimate
// is still an estimate, but at least it is wrong in the same direction for both
// languages instead of always cheapening Bengali.
const countTokens = (text) => {
  const str = String(text || '');
  const bengali = (str.match(/[\u0980-\u09FF]/g) || []).length;
  const latin = str.length - bengali;
  return Math.ceil(bengali / 1.7 + latin / 3.8);
};

const promptTokens = countTokens(fullInputStr) + 1350;
const completionTokens = countTokens(raw);
const totalTokens = promptTokens + completionTokens;


// A rule asked to speak before the agent does ("send this, then let the AI
// carry on"). The Gate already rendered the text; prepending it here is what
// makes that combination work — without it the canned message would be
// silently dropped, because the reply the customer sees is this one.
// try/catch because this workflow can also be run without the Gate present
// (older import), and `$(...)` throws on an unexecuted node.
let gateText = "";
try {
  gateText = $("Gate Decision").item.json.gateText || "";
} catch (err) {
  gateText = "";
}
if (gateText) replyText = gateText + "\n\n" + replyText;


return [{
  json: {
    replyText: replyText,
    galleryImages: [...new Set(imgs)],
    orderReceipt: orderReceipt || {},
    // Empty string when the agent did not ask for cards; the SQL below handles
    // that case without a second branch.
    carouselIds: carouselIds,
    carouselIdsSql: carouselIds.join(','),
    // Passed to Fetch Product Cards. When the customer asked for photos but the
    // agent emitted no marker, wantsCardsSql makes the SQL fall back to the
    // catalogue instead of returning nothing.
    wantsCardsSql: wantsCards ? '1' : '0',
    asksForImagesSql: asksForImages ? '1' : '0',
    isBroadBrowseSql: isBroadBrowse ? '1' : '0',
    userMessageSql: userMessageSql,
    quotedSnippetSqlLiteral: quotedSnippetSqlLiteral,
    promptTokens: promptTokens,
    completionTokens: completionTokens,
    totalTokens: totalTokens,
    tokensAreExact: false,
    // Media add-ons, decided in Merge Media where both branches meet.
    isImage: merge.isImage === true,
    audioMinutes: Number(merge.audioMinutes) || 0,
    llmCallCount: merge.isImage === true || Number(merge.audioMinutes) > 0 ? 2 : 1,
    model: model,
    timestamp: new Date().toISOString()
  }
}];

