// Collapse the engine's verdict into one boolean.
const gate = $input.item.json ?? {};
const ensureSession = $('Ensure Session')?.item?.json ?? {};

const sessionBlocked = ensureSession.isAiBlocked === true;
const sessionInactive = ensureSession.isActive === false;

const action = String(gate.action || "continue");
const muted = gate.muteAi === true || sessionBlocked || sessionInactive;
const continuesWithAi = gate.continueWithAi === true && !sessionBlocked && !sessionInactive;

const messages = Array.isArray(gate.messages) ? gate.messages : [];
const gateText = messages
  .map((message) => (message && typeof message.text === "string" ? message.text : ""))
  .filter(Boolean)
  .join("\n\n");

// If muted or session is blocked/inactive or canned reply without continuation: skip AI
const skipAi = muted || (action === "reply" && !continuesWithAi);

return [{ json: { ...gate, skipAi, gateText, sessionBlocked, sessionInactive } }];

// ─────────────────────────────────────────────────────────────────────────────
// Quota Blocked Reply
// The platform refused the AI call (credits exhausted, or the workspace was
// suspended). This node is where the turn ends instead of at `Return to Platform`.
//
// It deliberately does NOT chain into Save Chat History or Billing API: no model
// ran, so there is nothing to record and nothing to charge. `billingOk: true`
// carries the same meaning it does on `Gate Return` — "nothing further is owed
// for this turn" — which is what stops the caller from deducting anything.
// ─────────────────────────────────────────────────────────────────────────────
const verdict = $input.item.json ?? {};
// The customer-facing copy rides on the Gate's own answer now (`quota.replyText`)
// rather than on a separate `Quota Check` node — TASK-11 folded that call into
// `Automation Gate`, because it was a second round trip to the same platform.
// The `verdict.replyText` fallback covers an older Gate node during a version skew.
const copy = verdict.quota?.replyText ?? verdict.replyText ?? {};

// Which of the two copies to use. The AI Agent normally mirrors the customer's
// own language, but on these paths no model runs — so the only signal left is
// the script of the message the customer sent. Banglish (Bengali typed in Latin
// letters) reads as English here, which is the safe way to be wrong: the English
// copy is still a sentence a Bengali speaker understands.
const BENGALI = /[\u0980-\u09FF]/;
const userMessage = String($('When Called by Platform').item.json.userMessage || '');
const lang = BENGALI.test(userMessage) ? 'bn' : 'en';

// Reached only if the platform answered without copy — i.e. a version skew.
// Kept in English and kept short: it is the last resort, not the normal path.
const FALLBACK = "Sorry, I can't reply right now. Please message again in a little while.";
const replyText = copy[lang] || copy.en || FALLBACK;

return [{ json: {
  replyText,
  galleryImages: [],
  isOrderCreated: false,
  promptTokens: 0,
  completionTokens: 0,
  totalTokens: 0,
  costUsd: 0,
  costBdt: 0,
  creditsSpent: 0,
  billingOk: true,
  tokensAreExact: true
} }];

// ─────────────────────────────────────────────────────────────────────────────
// AI Failed Reply
// The AI Agent itself threw — the reply could not be generated at all.
//
// Why this node exists at all: n8n's OpenRouter Chat Model sub-node cannot send
// OpenRouter's `models: [...]` fallback list (it has no such field — see the
// `Quota Guard` sticky note), so a dead model id, a provider outage or n8n's own
// OpenRouter balance running dry have no second model to fall back to. Without
// this branch those failures ended as *silence*: the workflow errored before
// Format Response, the caller read an empty replyText, and on Facebook that
// became a Graph API call with an empty text — a 400 the customer never sees.
//
// This node cannot make the answer happen; it makes the *silence* not happen.
// ─────────────────────────────────────────────────────────────────────────────
// The copy comes from the platform (the same JSON the blocked path uses), so the
// customer-facing wording lives in one place. `try` because `$(...)` throws on a
// node that did not run — the same guard Format Response uses for the Gate.
//
// ⚡ Asked of `Gate Decision`, not of a `Quota Check` node: TASK-11 folded the
//    quota pre-flight into `Automation Gate` and deleted that node, and naming an
//    unexecuted node throws. Put `Quota Check` back and this must change with it.
let copy = {};
try {
  copy = $('Gate Decision').item.json.quota?.replyText ?? {};
} catch (err) {
  copy = {};
}

// Which of the two copies to use. The AI Agent normally mirrors the customer's
// own language, but on these paths no model runs — so the only signal left is
// the script of the message the customer sent. Banglish (Bengali typed in Latin
// letters) reads as English here, which is the safe way to be wrong: the English
// copy is still a sentence a Bengali speaker understands.
const BENGALI = /[\u0980-\u09FF]/;
const userMessage = String($('When Called by Platform').item.json.userMessage || '');
const lang = BENGALI.test(userMessage) ? 'bn' : 'en';

const FALLBACK = "Sorry, I can't reply right now. Please message again in a little while.";
const replyText = copy[lang] || copy.en || FALLBACK;

return [{ json: {
  replyText,
  galleryImages: [],
  isOrderCreated: false,
  promptTokens: 0,
  completionTokens: 0,
  totalTokens: 0,
  costUsd: 0,
  costBdt: 0,
  creditsSpent: 0,
  billingOk: true,
  tokensAreExact: true
} }];

// Gemini accepts the audio MIME types listed below; `audio/mp4` is NOT one of
// them — and that is exactly what Messenger voice notes arrive as. `audio/mp4`
// and `audio/m4a` are the same container under two labels, so the mapping is
// lossless, and it is what stops a Messenger voice note from killing the run.
const MAP = {
  'audio/mp4': 'audio/m4a',
  'audio/x-m4a': 'audio/m4a',
  'audio/m4a': 'audio/m4a',
  'audio/oga': 'audio/ogg',
  'application/ogg': 'audio/ogg',
  'audio/mpeg': 'audio/mp3',
  'audio/x-mpeg': 'audio/mp3',
  'audio/x-wav': 'audio/wav',
  'audio/wave': 'audio/wav',
};

const SUPPORTED = [
  'audio/wav', 'audio/mp3', 'audio/aiff', 'audio/aac', 'audio/ogg', 'audio/flac',
  'audio/mpeg', 'audio/m4a', 'audio/l16', 'audio/opus', 'audio/alaw', 'audio/mulaw',
  'audio/webm',
];

// Gemini's inline limit is 20 MB. 10 MB keeps us clear of it and matches the
// limit the platform already enforces for human agent attachments.
const MAX_BYTES = 10 * 1024 * 1024;

const binary = $binary.data || {};

// Declared types often carry parameters (e.g. 'audio/ogg; codecs=opus').
const declared = String(binary.mimeType || '').split(';')[0].trim().toLowerCase();
const mimeType = MAP[declared] || declared;

// n8n keeps binary as base64 in `data`; 3 bytes decode from every 4 characters.
const base64 = String(binary.data || '');
const audioBytes = base64 ? Math.floor((base64.length * 3) / 4) : 0;

const overLimit = audioBytes > MAX_BYTES;
const supported = SUPPORTED.includes(mimeType) && audioBytes > 0 && !overLimit;

// The fallback is what the AI is told to say when transcription cannot happen.
// It is written as an instruction, not as an apology, so the agent still answers
// usefully instead of echoing an error to the customer.
let audioFallbackText = '';
if (!supported) {
  audioFallbackText = overLimit
    ? '[The customer sent a voice message that is too long to process. Politely ask them to send a shorter one or type their question.]'
    : '[The customer sent a voice message that could not be transcribed. Politely ask them to type their question.]';
}

return {
  json: {
    ...$input.item.json,
    // Kept for storage: Cloudinary plays the file back in its original form.
    audioOriginalMimeType: declared,
    audioMimeType: mimeType,
    audioBase64: base64,
    audioBytes,
    audioSupported: supported,
    audioFallbackText,
  },
};

// ─────────────────────────────────────────────────────────────────────────────
// Merge Image Upload
// The HTTP Request node's output is Cloudinary's response — complete, but with
// none of the fields the next node needs. This restores the original item and
// adds the durable URL.
// ─────────────────────────────────────────────────────────────────────────────

const source = $('Code in JavaScript').first().json;
const response = $input.item.json || {};

const cloudinaryUrl = typeof response.secure_url === 'string' ? response.secure_url : '';

return {
  json: {
    ...source,
    cloudinaryUrl,
    cloudinaryPublicId: response.public_id || '',
    // Reported rather than thrown: the attachment is an addition to the answer,
    // never a dependency on it.
    cloudinaryError: cloudinaryUrl ? '' : 'Cloudinary returned no secure_url'
  }
};

// ─────────────────────────────────────────────────────────────────────────────
// Merge Audio Upload
// The HTTP Request node's output is Cloudinary's response — complete, but with
// none of the fields the next node needs. This restores the original item and
// adds the durable URL.
// ─────────────────────────────────────────────────────────────────────────────

const source = $('Normalize Audio Type').first().json;
const response = $input.item.json || {};

const cloudinaryUrl = typeof response.secure_url === 'string' ? response.secure_url : '';

return {
  json: {
    ...source,
    cloudinaryUrl,
    cloudinaryPublicId: response.public_id || '',
    // Reported rather than thrown: the attachment is an addition to the answer,
    // never a dependency on it.
    cloudinaryError: cloudinaryUrl ? '' : 'Cloudinary returned no secure_url'
  }
};
